import React, { useState, useEffect } from 'react';
import { database } from './firebase';
import { ref, onValue } from 'firebase/database';
import './Botstatus.css';

function Botstatus() {
  const [botData, setBotData] = useState(null);
  const [lastUpdate, setLastUpdate] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Function to fetch data from Firebase
  const fetchBotData = () => {
    try {
      const botStatsRef = ref(database, 'bot-stats');
      
      onValue(botStatsRef, (snapshot) => {
        const data = snapshot.val();
        if (data) {
          setBotData(data);
          setLastUpdate(new Date().toLocaleString());
          setLoading(false);
          setError(null);
        } else {
          setError('No data available');
          setLoading(false);
        }
      }, (error) => {
        setError(error.message);
        setLoading(false);
      });
    } catch (err) {
      setError(err.message);
      setLoading(false);
    }
  };

  useEffect(() => {
    // Initial fetch
    fetchBotData();

    // Set up polling every 2 minutes (120000 milliseconds)
    const interval = setInterval(() => {
      fetchBotData();
    }, 120000);

    // Cleanup interval on component unmount
    return () => clearInterval(interval);
  }, []);

  // Helper function to check if bot is online (last ping within 5 minutes)
  const isBotOnline = (lastPing) => {
    if (!lastPing) return false;
    const lastPingTime = new Date(lastPing).getTime();
    const now = new Date().getTime();
    const fiveMinutes = 5 * 60 * 1000;
    return (now - lastPingTime) < fiveMinutes;
  };

  // Helper function to format date
  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    return new Date(dateString).toLocaleString();
  };

  if (loading) {
    return (
      <div className="botstatus-container">
        <div className="loading">Loading bot status...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="botstatus-container">
        <div className="error">Error: {error}</div>
      </div>
    );
  }

  return (
    <div className="botstatus-container">
      <div className="header">
        <h1>Bot Status Dashboard</h1>
        <div className="last-update">Last Updated: {lastUpdate}</div>
        <div className="auto-refresh">Auto-refreshes every 2 minutes</div>
      </div>

      {botData && Object.entries(botData).map(([botId, bot]) => (
        <div key={botId} className="bot-card">
          <div className="bot-header">
            <h2>{botId}</h2>
            <span className={`status-indicator ${isBotOnline(bot.lastPing) ? 'online' : 'offline'}`}>
              {isBotOnline(bot.lastPing) ? '● ONLINE' : '● OFFLINE'}
            </span>
          </div>

          <div className="bot-info">
            <div className="info-row">
              <span className="label">Region:</span>
              <span className="value">{bot.region || 'N/A'}</span>
            </div>
            
            <div className="info-row">
              <span className="label">Last Ping:</span>
              <span className="value">{formatDate(bot.lastPing)}</span>
            </div>
            
            <div className="info-row">
              <span className="label">Last Relobby:</span>
              <span className="value">{formatDate(bot.lastRelobby)}</span>
            </div>
            
            <div className="info-row">
              <span className="label">Last Game Start:</span>
              <span className="value">{formatDate(bot.lastGameStart)}</span>
            </div>
            
            <div className="info-row">
              <span className="label">Connected Players:</span>
              <span className="value">{bot.amountOfConnected || 0}</span>
            </div>
          </div>

          {bot.connectedPlayers && Object.keys(bot.connectedPlayers).length > 0 && (
            <div className="connected-players">
              <h3>Connected Players:</h3>
              <ul>
                {Object.entries(bot.connectedPlayers).map(([time, name]) => (
                  <li key={time}>
                    <span className="player-name">{name}</span>
                    <span className="player-time">{time}</span>
                  </li>
                ))}
              </ul>
            </div>
          )}
        </div>
      ))}
    </div>
  );
}

export default Botstatus;
